import{_ as e,o as a,c as o,ag as t}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年7月26日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-26.md","filePath":"science-log/src/reconstructed/2026-07-26.md"}'),n={name:"science-log/src/reconstructed/2026-07-26.md"};function s(i,r,g,c,l,h){return a(),o("div",null,[...r[0]||(r[0]=[t('<h1 id="🔬-科学快报-2026年7月26日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月26日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月26日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月26日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 检索说明：2026-07-26 为<strong>周日</strong>。CrossRef 按 <code>from-pub-date=until-pub-date=2026-07-26</code> 检索，<strong>Nature（0028-0836）命中 0 条、PNAS（0027-8424）命中 0 条</strong>，Science 前缀 10.1126 当日仅命中 1 条（且为新闻稿，已剔除），即当日无研究论文出版。故科学 5 篇取自<strong>紧邻窗口（2026-07-22 ~ 2026-07-24）内的真实命中</strong>：Nature 2026-07-22（3 篇）、Science 2026-07-23（1 篇）、Science Advances 2026-07-24（1 篇）。AI 5 篇严格取自 arXiv <code>submittedDate:[202607260000 TO 202607262359]</code> 的 cs.AI 真实条目（命中 30 篇）。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607260000 TO 202607262359]</code>（cs.AI，30 条）+ EuropePMC 摘要核验 ｜ 重建日：2026-11-07</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-不打断裂双链的千碱基级「敲入」-knit-编辑" tabindex="-1">🧬 不打断裂双链的千碱基级「敲入」：KNIT 编辑 <a class="header-anchor" href="#🧬-不打断裂双链的千碱基级「敲入」-knit-编辑" aria-label="Permalink to &quot;🧬 不打断裂双链的千碱基级「敲入」：KNIT 编辑&quot;">​</a></h3><p><strong>Efficient and precise programmable DNA knock-in without double-strand breaks</strong><em>Nature（2026-07-22 在线）</em></p><p>现有基因敲入多依赖 Cas9 切断双链再靠同源重组修补，切口一开，插入缺失（indel）、染色体易位和脱靶就跟着来，且片段越长越难。作者（Gao Y、Ma Y、Yu K、Wang H 等）改用<strong>切口酶（nickase）+ 供体 DNA 招募系统</strong>耦合的方案，命名为 KNIT（CRISPR kilobase-scale nickase-targeting editing）：只在单链上开切口，把供体直接拉到切口处，从而实现 0.7 kb 至 10 kb 以上片段的程序化整合，跨不同基因组位点与细胞类型均有效。其效率最高达 <strong>89%</strong>，同时显著压低 indel、易位与脱靶率；系统支持反复插入与多位点敲入，升级版 KNIT editor 2 用一次转染即可进一步提升效率。在携带致病突变的细胞中，KNIT 通过插入正常序列恢复了基因表达——这使「大片段安全写入」从概念走向可用工具。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10819-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10819-7</a></p><h3 id="⚛️-相变点上序参量「不是高斯」-在格点玻色气体里直接测出整条概率分布" tabindex="-1">⚛️ 相变点上序参量「不是高斯」：在格点玻色气体里直接测出整条概率分布 <a class="header-anchor" href="#⚛️-相变点上序参量「不是高斯」-在格点玻色气体里直接测出整条概率分布" aria-label="Permalink to &quot;⚛️ 相变点上序参量「不是高斯」：在格点玻色气体里直接测出整条概率分布&quot;">​</a></h3><p><strong>Non-Gaussian statistics of the order parameter across a phase transition</strong><em>Nature（2026-07-22 在线）</em></p><p>二阶相变的教科书叙事靠临界指数与普适类，但序参量本身的<strong>概率分布</strong>在相变前后如何变形，长期只有理论预言、缺少直接测量。作者（Allemand M、Dupuy G、Chalopin T、Clément D 等，含理论合作者 Rançon A、Roscilde T）用<strong>单原子分辨的动量空间探测</strong>，在相互作用格点玻色气的连续相变（超流—正常）两侧，测出序参量振幅的完整概率分布。他们仿照 Landau 理论从实测分布反演出<strong>有效势</strong>：在超流（有序）相中出现非平庸极小值，并在相变点消失。分布明显偏离高斯，说明临界区涨落的非线性耦合被完整捕捉——这把「普适性」从几个数字（指数）扩展成一条可测的分布曲线。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10811-1" target="_blank" rel="noreferrer">10.1038/s41586-026-10811-1</a></p><h3 id="🪐-褐矮星旁的「行星质量卫星」-首次用视向速度在直接成像伴星上找到证据" tabindex="-1">🪐 褐矮星旁的「行星质量卫星」：首次用视向速度在直接成像伴星上找到证据 <a class="header-anchor" href="#🪐-褐矮星旁的「行星质量卫星」-首次用视向速度在直接成像伴星上找到证据" aria-label="Permalink to &quot;🪐 褐矮星旁的「行星质量卫星」：首次用视向速度在直接成像伴星上找到证据&quot;">​</a></h3><p><strong>Planetary-mass exosatellite detected around the substellar companion of a star</strong><em>Nature（2026-07-22 在线）</em></p><p>六千多颗系外行星已确认，但<strong>系外卫星（exomoon）<strong>始终没有一例被确信证认，候选者都困在争议里。作者（Hoy K、Zurlo A、Peña P. A.、Köhler J、Desidera S、Gratton R 等）把发现第一颗系外行星时用的</strong>视向速度法</strong>，用到已直接成像的褐矮星伴星 <strong>CD-35 2722 B</strong> 的 VLT/CRIRES+ 光谱上，发现周期性的速度信号，符合至少一颗卫星绕其运行。褐矮星处在行星与恒星之间的质量区间，其卫星该不该叫「系外月亮」尚无正式定义，因此这项工作同时推进了观测与命名两件事。若后续独立观测确认，它将是首个围绕亚恒星伴星的行星质量卫星系统。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10751-w" target="_blank" rel="noreferrer">10.1038/s41586-026-10751-w</a></p><h3 id="🧠-单细胞里同时看-3d-基因组与转录组-阿尔茨海默病的「染色质重构」图谱" tabindex="-1">🧠 单细胞里同时看 3D 基因组与转录组：阿尔茨海默病的「染色质重构」图谱 <a class="header-anchor" href="#🧠-单细胞里同时看-3d-基因组与转录组-阿尔茨海默病的「染色质重构」图谱" aria-label="Permalink to &quot;🧠 单细胞里同时看 3D 基因组与转录组：阿尔茨海默病的「染色质重构」图谱&quot;">​</a></h3><p><strong>Single-cell multiomics connects 3D genome and transcriptome alterations in Alzheimer&#39;s disease</strong><em>Science（2026-07-23）</em></p><p>阿尔茨海默病（AD）的分子病理长期以转录组与表观修饰为主角，<strong>三维基因组组织</strong>的贡献几乎是空白。作者（Zhang Y、Lu X、Kunisky A. K. 等）用 <strong>GAGE-seq</strong>（genome architecture and gene expression by sequencing）在 AD 患者与年龄匹配对照的尸检脑组织单细胞中，同时测基因表达与 3D 染色质结构，发现与细胞类型特异性失调相耦合的染色质重排。把结果与空间转录组、染色质可及性数据整合后，他们识别出反映基因组区室（compartment）重塑与调控元件重排的异常微环境；并训练深度学习框架 <strong>Hicformer</strong> 证明：3D 基因组特征对预测疾病相关的细胞类型特异表达变化是<strong>必需的</strong>，而非可有可无的附加项。这把「高阶染色质改变」正式写进 AD 的分子病理清单。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adz1652" target="_blank" rel="noreferrer">10.1126/science.adz1652</a></p><h3 id="☁️-7083-次高分辨率模拟-太平洋低云是正反馈-且在-4×co2-下显著非线性增强" tabindex="-1">☁️ 7083 次高分辨率模拟：太平洋低云是<strong>正</strong>反馈，且在 4×CO₂ 下显著非线性增强 <a class="header-anchor" href="#☁️-7083-次高分辨率模拟-太平洋低云是正反馈-且在-4×co2-下显著非线性增强" aria-label="Permalink to &quot;☁️ 7083 次高分辨率模拟：太平洋低云是**正**反馈，且在 4×CO₂ 下显著非线性增强&quot;">​</a></h3><p><strong>High-resolution simulations reveal positive global warming feedback from Pacific low clouds</strong><em>Science Advances（2026-07-24）</em></p><p>海洋低云反馈是气候预估最大的不确定性来源之一。作者（Chammas S、Wang Q、Schneider T、Ihme M、Anderson J 等）跑 <strong>7083 次</strong>热带太平洋低云高分辨率模拟，把<strong>海表增温</strong>的效应与<strong>CO₂ 直接效应</strong>拆开。单看增温，低云反馈为正；这一项在 CO₂ 加倍时变化不大，但到 CO₂ 四倍时<strong>总云辐射响应明显增强</strong>，暴露出强烈的非线性相互作用。机制上：增温通过逆温层增强与下沉减弱改造边界层，一方面提高云内液水含量（「增亮」，起缓冲作用），另一方面降低云量；而高 CO₂ 的快速调整恰好<strong>抵消</strong>了这种保护性增厚。结果是云量减少不再被云亮度增加所补偿，总反馈被显著放大——这直接压缩了气候敏感度的乐观区间。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aec8488" target="_blank" rel="noreferrer">10.1126/sciadv.aec8488</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧰-acm-让智能体自己决定「何时压缩上下文、把什么扔进外部记忆」" tabindex="-1">🧰 ACM：让智能体自己决定「何时压缩上下文、把什么扔进外部记忆」 <a class="header-anchor" href="#🧰-acm-让智能体自己决定「何时压缩上下文、把什么扔进外部记忆」" aria-label="Permalink to &quot;🧰 ACM：让智能体自己决定「何时压缩上下文、把什么扔进外部记忆」&quot;">​</a></h3><p><strong>ACM: Agentic Context Management for Long Horizon Tasks</strong><em>arXiv（2026-07-26，cs.AI）</em></p><p>智能体任务是长时程、多轮的，上下文随交互不断堆积；现有压缩方法必然丢信息，且由<strong>僵硬的启发式规则</strong>触发，与智能体当下的推理焦点错位。作者（Xiaochuan Li、Ryan Ming、Meng Chu、Shuai Shao、Rong Jin）提出 <strong>Agentic Context Management（ACM）</strong>：给智能体配一套专用的上下文编辑工具，做<strong>无损</strong>管理——由智能体自主判断何时压缩，把被丢弃的内容<strong>卸载到外部记忆系统</strong>，需要时再按需检索回来。类比人类短时记忆与长时记忆的交互。配套的后训练流水线构造高质量「上下文管理示范」，在智能体检索与编码任务上同时提升表现；分析显示，有效管理降低了峰值 token 压力，允许更长的探索，并使多次独立试验的解更一致。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.23809" target="_blank" rel="noreferrer">2607.23809</a></p><h3 id="⚖️-模型合并的「不对称崩塌」-拒答能力压过识别能力" tabindex="-1">⚖️ 模型合并的「不对称崩塌」：拒答能力压过识别能力 <a class="header-anchor" href="#⚖️-模型合并的「不对称崩塌」-拒答能力压过识别能力" aria-label="Permalink to &quot;⚖️ 模型合并的「不对称崩塌」：拒答能力压过识别能力&quot;">​</a></h3><p><strong>Asymmetric Collapse in Model Merging: When Refusal Overwrites Recognition</strong><em>arXiv（2026-07-26，cs.AI）</em></p><p>模型合并常被用来零训练拼装多个微调模型的能力，但这些方法能否<strong>同时</strong>保住多种安全行为，此前没人系统检验。作者（Aarnav Choudhary、Matheus Fonseca Rocha、Jiwon Seo、Vasu Sharma、Maheep Chaudhary）用 Gemma-3-1B-IT 的两个微调版本做受控案例：一个学 CARES 危害等级分类，一个学 WildJailbreak 对抗性拒答；再用 Linear、SLERP、TIES、DARE-TIES 四种方法合并。结果是<strong>稳定的不对称</strong>：合并后越狱拒答率保留 81–85%，而 CARES 分类准确率最多只剩 12.9%。权重空间测量排除了「任务向量强烈对冲」这一解释——两者几乎正交（余弦相似度 0.011）；真正原因是拒答微调在<strong>逐层任务向量模长</strong>上系统性更大，于是对幅度敏感的方法天然偏向拒答更新。结论很硬：标准合并会让「会拒答」淹没「会识别」，安全检查因此形同虚设。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.27240" target="_blank" rel="noreferrer">2607.27240</a></p><h3 id="🗄️-冻结的-12b-一块已验证记忆库-九族-180-题全对、零生成-token" tabindex="-1">🗄️ 冻结的 12B + 一块已验证记忆库：九族 180 题全对、零生成 token <a class="header-anchor" href="#🗄️-冻结的-12b-一块已验证记忆库-九族-180-题全对、零生成-token" aria-label="Permalink to &quot;🗄️ 冻结的 12B + 一块已验证记忆库：九族 180 题全对、零生成 token&quot;">​</a></h3><p><strong>A Frozen 12B Beats Frontier Models on Verified Work: 100% Accuracy, 0 Tokens, Bit-Exact, Forever</strong><em>arXiv（2026-07-26，cs.CL/cs.AI/cs.IR）</em></p><p>主流思路是「想更强就重训」，代价是巨额算力、每轮一个新黑箱、输出不可复现。作者（Sietse Schelpe）走反路：<strong>模型冻结不动</strong>，在旁生长一个<strong>已验证解</strong>的持久记忆库——某问题族一旦被解出并通过<strong>不查答案键</strong>的独立验证，之后同族每个新实例都以<strong>零生成 token、逐比特一致、确定性</strong>的方式作答。在覆盖九个问题族的 180 个新实例上，来自四家厂商的四种架构（dense 与 MoE）各自都拿到 <strong>180/180</strong>，且每题生成 token 为零：执行能力与参数规模<strong>解耦</strong>。负对照确认能力完全来自记忆——清空记忆后一题也解不出。同类契约在开放式推理上同样成立：四模型共 88/88 次一致性门控接受、机器可查的形式证明、推理方法迁移 77/80；记忆选择耗时 1.4 微秒，一次完整复用 6–23 毫秒、36 mWh。附带还测出近似相似度检索在 4500 条已验证库上挑错率高达 94.3%。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.23806" target="_blank" rel="noreferrer">2607.23806</a></p><h3 id="📉-按学习率比例缩放权重衰减-muon-sw-保住稳定性又不改渐近解" tabindex="-1">📉 按学习率比例缩放权重衰减：Muon-SW 保住稳定性又不改渐近解 <a class="header-anchor" href="#📉-按学习率比例缩放权重衰减-muon-sw-保住稳定性又不改渐近解" aria-label="Permalink to &quot;📉 按学习率比例缩放权重衰减：Muon-SW 保住稳定性又不改渐近解&quot;">​</a></h3><p><strong>Scale Weight Decay and Train Better</strong><em>arXiv（2026-07-26，cs.LG/cs.AI）</em></p><p>规模定律推动模型在越来越大的数据上训练，而常规做法是<strong>恒定的解耦权重衰减</strong>，结果是权重模长随训练一路缩水，等于悄悄改变了优化目标。作者（Anuj Apte）借鉴 Robbins–Monro 条件，提出按<strong>峰值学习率比例 η/η_max</strong> 缩放权重衰减，并证明：对随机梯度下降与<strong>非欧几里得谱优化器 Muon</strong> 都保持无正则方法原有的渐近平稳性保证，从而消除恒定解耦衰减带来的额外渐近偏置。稳态分析解释了差别——标准衰减下权重模长持续下降，缩放衰减下则落到近似常数。在 MoE 模型训练上，同超参下 Muon-SW 稳定优于 Muon，更快到达同一验证损失。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.23777" target="_blank" rel="noreferrer">2607.23777</a></p><h3 id="🔭-库仑斥力当正则-用「粒子」学出-transformer-的核注意力分布" tabindex="-1">🔭 库仑斥力当正则：用「粒子」学出 Transformer 的核注意力分布 <a class="header-anchor" href="#🔭-库仑斥力当正则-用「粒子」学出-transformer-的核注意力分布" aria-label="Permalink to &quot;🔭 库仑斥力当正则：用「粒子」学出 Transformer 的核注意力分布&quot;">​</a></h3><p><strong>A Coulomb Particle Model for Learning Kernel Attention in Transformers</strong><em>arXiv（2026-07-26，cs.LG/cs.AI）</em></p><p>随机特征能以线性复杂度逼近核机器，但性能高度依赖<strong>特征分布怎么选</strong>，历来靠拍脑袋。作者（Masoud Badiei Khuzani、Sharath Honnaiah、Atiq Islam、Alex Cozzi、Abraham Bagherjeiran）用<strong>粒子法</strong>学这个分布：以核—目标对齐（kernel-target alignment）为目标函数，同时用 <strong>Riesz/库仑斥力势</strong>正则化粒子，使粒子自动散开、覆盖任务真正需要的方向。得到的哈密顿量有<strong>平均场</strong>描述，满足 McKean–Vlasov 方程——粒子动力学被一个偏微分方程严格刻画。他们把它落到线性化 Transformer 注意力上：第一阶段学出正随机特征映射，随后<strong>冻结核</strong>、用交叉熵训练其余参数。实验显示学到的核注意力在准确率、校准与鲁棒性上均有提升，同时保住线性注意力的推理复杂度。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.23869" target="_blank" rel="noreferrer">2607.23869</a></p><blockquote><p>📅 日期：2026-07-26 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const m=e(n,[["render",s]]);export{p as __pageData,m as default};
